// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        address admin = address(this);
        address initialOwner = c.owner();
        vm.prank(caller);
        try c.setOwner(newOwner) { } catch { }
        address finalOwner = c.owner();
        assertTrue(finalOwner == initialOwner || (caller == admin && finalOwner == newOwner));
    }
}
